                            HtmlBody = "<!DOCTYPE html>\r\n<html>\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n<style>\r\n    body {\r\n        font-family: Arial, Helvetica, sans-serif;\r\n        font-size: 11px;\r\n        color: #333;\r\n        margin: 25px 30px;\r\n        line-height: 1.4;\r\n    }\r\n\r\n    /* ── Supplier (DODAVATEL) section ── */\r\n    table.issuer-block {\r\n        width: 100%;\r\n        border-collapse: collapse;\r\n        margin-bottom: 15px;\r\n    }\r\n    table.issuer-block td {\r\n        vertical-align: top;\r\n        padding: 2px 0;\r\n    }\r\n    .issuer-label {\r\n        font-size: 10px;\r\n        color: #777;\r\n        text-transform: uppercase;\r\n        letter-spacing: 0.5px;\r\n        padding-bottom: 4px;\r\n    }\r\n    .issuer-name {\r\n        font-size: 13px;\r\n        font-weight: bold;\r\n        color: #333;\r\n    }\r\n    .issuer-detail {\r\n        color: #555;\r\n        font-size: 11px;\r\n    }\r\n\r\n    /* ── Green header bar — visually distinguishes pro-forma from a real tax invoice ── */\r\n    table.doc-header {\r\n        width: 100%;\r\n        border-collapse: collapse;\r\n        margin: 12px 0 15px 0;\r\n    }\r\n    .doc-header-bar {\r\n        background-color: #3D7A4A;\r\n        color: #fff;\r\n        padding: 8px 12px;\r\n        font-size: 12px;\r\n    }\r\n    .doc-header-bar .doc-type {\r\n        font-size: 14px;\r\n        font-weight: bold;\r\n        text-transform: uppercase;\r\n    }\r\n    .doc-header-bar .doc-subtitle {\r\n        font-size: 10px;\r\n        font-weight: bold;\r\n        text-transform: uppercase;\r\n    }\r\n    .doc-number-cell {\r\n        background-color: #3D7A4A;\r\n        color: #fff;\r\n        text-align: right;\r\n        padding: 8px 12px;\r\n        font-size: 22px;\r\n        font-weight: bold;\r\n        letter-spacing: 1px;\r\n    }\r\n\r\n    /* ── Notice banner — reminds recipient this is NOT a VAT tax document ── */\r\n    .not-tax-doc-notice {\r\n        background-color: #FFF8E1;\r\n        border: 1px solid #FFE082;\r\n        color: #795548;\r\n        padding: 6px 12px;\r\n        font-size: 10px;\r\n        margin-bottom: 12px;\r\n        font-style: italic;\r\n    }\r\n\r\n    /* ── Client (ODBĚRATEL) + dates section ── */\r\n    table.client-dates {\r\n        width: 100%;\r\n        border-collapse: collapse;\r\n        margin-bottom: 20px;\r\n    }\r\n    table.client-dates td {\r\n        vertical-align: top;\r\n        padding: 2px 0;\r\n    }\r\n    .client-label {\r\n        font-size: 10px;\r\n        color: #777;\r\n        text-transform: uppercase;\r\n        letter-spacing: 0.5px;\r\n        padding-bottom: 4px;\r\n    }\r\n    .client-name {\r\n        font-weight: bold;\r\n        font-size: 12px;\r\n    }\r\n    .date-label {\r\n        color: #777;\r\n        font-size: 10px;\r\n        text-transform: uppercase;\r\n        padding: 3px 10px 3px 0;\r\n    }\r\n    .date-value {\r\n        text-align: right;\r\n        font-weight: bold;\r\n        padding: 3px 0;\r\n    }\r\n\r\n    /* ── Items table ── */\r\n    table.items {\r\n        width: 100%;\r\n        border-collapse: collapse;\r\n        margin: 5px 0 15px 0;\r\n    }\r\n    table.items th {\r\n        background-color: #3D7A4A;\r\n        color: #fff;\r\n        padding: 6px 8px;\r\n        font-size: 10px;\r\n        text-transform: uppercase;\r\n        font-weight: bold;\r\n        text-align: left;\r\n    }\r\n    table.items td {\r\n        padding: 6px 8px;\r\n        border-bottom: 1px solid #e0e0e0;\r\n        font-size: 11px;\r\n    }\r\n\r\n    /* ── VAT breakdown + grand total ── */\r\n    table.vat-summary {\r\n        width: 100%;\r\n        border-collapse: collapse;\r\n        margin-top: 10px;\r\n    }\r\n    table.vat-summary th {\r\n        background-color: #e8e8e8;\r\n        padding: 5px 10px;\r\n        font-size: 10px;\r\n        text-transform: uppercase;\r\n        font-weight: bold;\r\n        text-align: center;\r\n    }\r\n    table.vat-summary td {\r\n        padding: 4px 10px;\r\n        font-size: 11px;\r\n    }\r\n    .grand-total-row {\r\n        background-color: #f0f0f0;\r\n    }\r\n    .grand-total-row td {\r\n        font-weight: bold;\r\n        font-size: 13px;\r\n        padding: 8px 10px;\r\n        text-transform: uppercase;\r\n    }\r\n\r\n    /* ── Payment info + QR code ── */\r\n    table.payment-info {\r\n        width: 100%;\r\n        border-collapse: collapse;\r\n        margin-top: 20px;\r\n    }\r\n    table.payment-info td {\r\n        vertical-align: top;\r\n        padding: 2px 5px;\r\n    }\r\n    .payment-label {\r\n        color: #777;\r\n        font-size: 10px;\r\n    }\r\n\r\n    /* ── Separator line ── */\r\n    .separator {\r\n        border: none;\r\n        border-top: 1px solid #ccc;\r\n        margin: 10px 0;\r\n    }\r\n</style>\r\n</head>\r\n<body>\r\n\r\n<!-- ═══════ ISSUER (DODAVATEL) SECTION ═══════ -->\r\n<table class=\"issuer-block\">\r\n    <tr>\r\n        <td style=\"width:50%\">\r\n            <div class=\"issuer-label\">DODAVATEL</div>\r\n            <div class=\"issuer-name\">{{IssuerName}}</div>\r\n            <div class=\"issuer-detail\">{{IssuerStreet}}</div>\r\n            <div class=\"issuer-detail\">{{IssuerPostalCode}} {{IssuerCity}}</div>\r\n            <div class=\"issuer-detail\">{{IssuerCountry}}</div>\r\n        </td>\r\n        <td style=\"width:50%; text-align:right\">\r\n            <table style=\"margin-left:auto; border-collapse:collapse;\">\r\n                <tr><td class=\"issuer-detail\" style=\"text-align:left; padding:1px 5px;\">Tel:</td><td class=\"issuer-detail\" style=\"padding:1px 5px;\">{{IssuerPhone}}</td></tr>\r\n                <tr><td class=\"issuer-detail\" style=\"text-align:left; padding:1px 5px;\">Email:</td><td class=\"issuer-detail\" style=\"padding:1px 5px;\">{{IssuerEmail}}</td></tr>\r\n                <tr><td class=\"issuer-detail\" style=\"text-align:left; padding:1px 5px;\">IČ:</td><td class=\"issuer-detail\" style=\"padding:1px 5px;\">{{IssuerRegistrationNumber}}</td></tr>\r\n                <tr><td class=\"issuer-detail\" style=\"text-align:left; padding:1px 5px;\">DIČ:</td><td class=\"issuer-detail\" style=\"padding:1px 5px;\">{{IssuerTaxNumber}}</td></tr>\r\n                <tr><td class=\"issuer-detail\" style=\"text-align:left; padding:1px 5px;\">B.Ú.:</td><td class=\"issuer-detail\" style=\"padding:1px 5px;\">{{BankAccountNumber}}</td></tr>\r\n            </table>\r\n        </td>\r\n    </tr>\r\n</table>\r\n\r\n<!-- ═══════ DOCUMENT HEADER BAR — green accent for pro-forma ═══════ -->\r\n<table class=\"doc-header\">\r\n    <tr>\r\n        <td class=\"doc-header-bar\" style=\"width:60%\">\r\n            <span class=\"doc-type\">{{DocumentTypeLabel}}</span>\r\n            <span style=\"font-size:11px; font-weight:normal;\">(variabilní symbol)</span>\r\n            <br/>\r\n            <span class=\"doc-subtitle\">ZÁLOHOVÁ FAKTURA — NENÍ DAŇOVÝ DOKLAD</span>\r\n        </td>\r\n        <td class=\"doc-number-cell\">{{VariableSymbol}}</td>\r\n    </tr>\r\n</table>\r\n\r\n<!-- ═══════ NOT-A-TAX-DOCUMENT NOTICE ═══════ -->\r\n<div class=\"not-tax-doc-notice\">\r\n    Tato zálohová faktura není daňovým dokladem ve smyslu zákona o DPH.\r\n    Daňový doklad bude vystaven po přijetí platby.\r\n</div>\r\n\r\n<!-- ═══════ CLIENT (ODBĚRATEL) + DATES ═══════ -->\r\n<table class=\"client-dates\">\r\n    <tr>\r\n        <td style=\"width:50%\">\r\n            <div class=\"client-label\">ODBĚRATEL</div>\r\n            <div class=\"client-name\">{{ClientName}}</div>\r\n            <div class=\"issuer-detail\">{{ClientStreet}}</div>\r\n            <div class=\"issuer-detail\">{{ClientPostalCode}} {{ClientCity}}</div>\r\n            <div class=\"issuer-detail\">IČ: {{ClientRegistrationNumber}}</div>\r\n            <div class=\"issuer-detail\">DIČ: {{ClientTaxNumber}}</div>\r\n        </td>\r\n        <td style=\"width:50%; vertical-align:top; padding-left:30px;\">\r\n            <table style=\"width:100%; border-collapse:collapse;\">\r\n                <tr><td class=\"date-label\">DATUM VYSTAVENÍ</td><td class=\"date-value\">{{IssueDate}}</td></tr>\r\n                <tr><td class=\"date-label\">DATUM SPLATNOSTI</td><td class=\"date-value\">{{DueDate}}</td></tr>\r\n                <tr><td class=\"date-label\">FORMA ÚHRADY</td><td class=\"date-value\">{{PaymentMethod}}</td></tr>\r\n            </table>\r\n        </td>\r\n    </tr>\r\n</table>\r\n\r\n<hr class=\"separator\" />\r\n\r\n<!-- ═══════ INVOICE ITEMS TABLE ═══════ -->\r\n<table class=\"items\">\r\n    <thead>\r\n        <tr>\r\n            <th style=\"width:40%\">POPIS POLOŽKY</th>\r\n            <th style=\"text-align:center; width:8%\">MJ</th>\r\n            <th style=\"text-align:center; width:8%\">DPH</th>\r\n            <th style=\"text-align:center; width:8%\">POČET</th>\r\n            <th style=\"text-align:right; width:18%\">CENA/MJ</th>\r\n            <th style=\"text-align:right; width:18%\">CELKEM BEZ DPH</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        {{InvoiceItems}}\r\n    </tbody>\r\n</table>\r\n\r\n<!-- ═══════ VAT BREAKDOWN + GRAND TOTAL ═══════ -->\r\n<table class=\"vat-summary\">\r\n    <thead>\r\n        <tr>\r\n            <th style=\"width:34%\">SAZBA</th>\r\n            <th style=\"width:33%; text-align:right\">ZÁKLAD</th>\r\n            <th style=\"width:33%; text-align:right\">DPH</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        {{VatBreakdown}}\r\n    </tbody>\r\n</table>\r\n\r\n<table class=\"vat-summary\" style=\"margin-top:0\">\r\n    <tr class=\"grand-total-row\">\r\n        <td style=\"width:67%\">CELKEM K ÚHRADĚ (záloha)</td>\r\n        <td style=\"width:33%; text-align:right\">{{TotalWithVat}} {{CurrencySymbol}}</td>\r\n    </tr>\r\n</table>\r\n\r\n<!-- ═══════ QR CODE (if available) ═══════ -->\r\n<table class=\"payment-info\">\r\n    <tr>\r\n        <td style=\"text-align:right\">\r\n            {{QrCodeImage}}\r\n        </td>\r\n    </tr>\r\n</table>\r\n\r\n</body>\r\n</html>\r\n",
