r\n    }\r\n\r\n    /* ── Payment info + QR code ── */\r\n    table.payment-info {\r\n        width: 100%;\r\n        border-collapse: collapse;\r\n        margin-top: 20px;\r\n    }\r\n    table.payment-info td {\r\n        vertical-align: top;\r\n        padding: 2px 5px;\r\n    }\r\n    .payment-label {\r\n        color: #777;\r\n        font-size: 10px;\r\n    }\r\n\r\n    /* ── Separator line ── */\r\n    .separator {\r\n        border: none;\r\n        border-top: 1px solid #ccc;\r\n        margin: 10px 0;\r\n    }\r\n</style>\r\n</head>\r\n<body>\r\n\r\n<!-- ═══════ ISSUER (DODAVATEL) SECTION ═══════ -->\r\n<table class=\"issuer-block\">\r\n    <tr>\r\n        <td style=\"width:50%\">\r\n            <div class=\"issuer-label\">DODAVATEL</div>\r\n            <div class=\"issuer-name\">{{IssuerName}}</div>\r\n            <div class=\"issuer-detail\">{{IssuerStreet}}</div>\r\n            <div class=\"issuer-detail\">{{IssuerPostalCode}} {{IssuerCity}}</div>\r\n            <div class=\"issuer-detail\">{{IssuerCountry}}</div>\r\n        </td>\r\n        <td style=\"width:50%; text-align:right\">\r\n            <table style=\"margin-left:auto; border-collapse:collapse;\">\r\n                <tr><td class=\"issuer-detail\" style=\"text-align:left; padding:1px 5px;\">Tel:</td><td class=\"issuer-detail\" style=\"padding:1px 5px;\">{{IssuerPhone}}</td></tr>\r\n                <tr><td class=\"issuer-detail\" style=\"text-align:left; padding:1px 5px;\">Email:</td><td class=\"issuer-detail\" style=\"padding:1px 5px;\">{{IssuerEmail}}</td></tr>\r\n                <tr><td class=\"issuer-detail\" style=\"text-align:left; padding:1px 5px;\">IČ:</td><td class=\"issuer-detail\" style=\"padding:1px 5px;\">{{IssuerRegistrationNumber}}</td></tr>\r\n                <tr><td class=\"issuer-detail\" style=\"text-align:left; padding:1px 5px;\">DIČ:</td><td class=\"issuer-detail\" style=\"padding:1px 5px;\">{{IssuerTaxNumber}}</td></tr>\r\n                <tr><td class=\"issuer-detail\" style=\"text-align:left; padding:1px 5px;\">B.Ú.:</td><td class=\"issuer-detail\" style=\"padding:1px 5px;\">{{BankAccountNumber}}</td></tr>\r\n            </table>\r\n        </td>\r\n    </tr>\r\n</table>\r\n\r\n<!-- ═══════ DOCUMENT HEADER BAR — purple accent for tax receipt ═══════ -->\r\n<table class=\"doc-header\">\r\n    <tr>\r\n        <td class=\"doc-header-bar\" style=\"width:60%\">\r\n            <span class=\"doc-type\">{{DocumentTypeLabel}}</span>\r\n            <span style=\"font-size:11px; font-weight:normal;\">(variabilní symbol)</span>\r\n            <br/>\r\n            <span class=\"doc-subtitle\">DAŇOVÝ DOKLAD O PŘIJATÉ PLATBĚ</span>\r\n        </td>\r\n        <td class=\"doc-number-cell\">{{VariableSymbol}}</td>\r\n    </tr>\r\n</table>\r\n\r\n<!-- ═══════ CLIENT (ODBĚRATEL) + DATES ═══════ -->\r\n<table class=\"client-dates\">\r\n    <tr>\r\n        <td style=\"width:50%\">\r\n            <div class=\"client-label\">ODBĚRATEL</div>\r\n            <div class=\"client-name\">{{ClientName}}</div>\r\n            <div class=\"issuer-detail\">{{ClientStreet}}</div>\r\n            <div class=\"issuer-detail\">{{ClientPostalCode}} {{ClientCity}}</div>\r\n            <div class=\"issuer-detail\">IČ: {{ClientRegistrationNumber}}</div>\r\n            <div class=\"issuer-detail\">DIČ: {{ClientTaxNumber}}</div>\r\n        </td>\r\n        <td style=\"width:50%; vertical-align:top; padding-left:30px;\">\r\n            <table style=\"width:100%; border-collapse:collapse;\">\r\n                <tr><td class=\"date-label\">DATUM VYSTAVENÍ</td><td class=\"date-value\">{{IssueDate}}</td></tr>\r\n                <tr><td class=\"date-label\">DATUM SPLATNOSTI</td><td class=\"date-value\">{{DueDate}}</td></tr>\r\n                <tr><td class=\"date-label\">DATUM ZDAN. PLNĚNÍ</td><td class=\"date-value\">{{TaxableSupplyDate}}</td></tr>\r\n                <tr><td class=\"date-label\">FORMA ÚHRADY</td><td class=\"date-value\">{{PaymentMethod}}</td></tr>\r\n            </table>\r\n        </td>\r\n    </tr>\r\n</table>\r\n\r\n<hr class=\"separator\" />\r\n\r\n<!-- ═══════ INVOICE ITEMS TABLE ═══════ -->\r\n<table class=\"items\">\r\n    <thead>\r\n        <tr>\r\n            <th style=\"width:40%\">POPIS POLOŽKY</th>\r\n            <th style=\"text-align:center; width:8%\">MJ</th>\r\n            <th style=\"text-align:center; width:8%\">DPH</th>\r\n            <th style=\"text-align:center; width:8%\">POČET</th>\r\n            <th style=\"text-align:right; width:18%\">CENA/MJ</th>\r\n            <th style=\"text-align:right; width:18%\">CELKEM BEZ DPH</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        {{InvoiceItems}}\r\n    </tbody>\r\n</table>\r\n\r\n<!-- ═══════ VAT BREAKDOWN + GRAND TOTAL ═══════ -->\r\n<table class=\"vat-summary\">\r\n    <thead>\r\n        <tr>\r\n            <th style=\"width:34%\">SAZBA</th>\r\n            <th style=\"width:33%; text-align:right\">ZÁKLAD</th>\r\n            <th style=\"width:33%; text-align:right\">DPH</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        {{VatBreakdown}}\r\n    </tbody>\r\n</table>\r\n\r\n<table class=\"vat-summary\" style=\"margin-top:0\">\r\n    <tr class=\"grand-total-row\">\r\n        <td style=\"width:67%\">UHRAZENO (přijatá platba)</td>\r\n        <td style=\"width:33%; text-align:right\">{{TotalWithVat}} {{CurrencySymbol}}</td>\r\n    </tr>\r\n</table>\r\n\r\n<!-- ═══════ QR CODE (if available) ═══════ -->\r\n<table class=\"payment-info\">\r\n    <tr>\r\n        <td style=\"text-align:right\">\r\n            {{QrCodeImage}}\r\n        </td>\r\n    </tr>\r\n</table>\r\n\r\n</body>\r\n</html>\r\n",
                            IsActive = true,
                            IsDefault = true,
                            Language = "cs",
                            Name = "Default Tax Receipt for Advance PDF",
                            TemplateType = 5
                        },
